export interface Header {
  name: string;
  value: string;
}

export function readHeaders(lines: string[]): Header[] {
  const headers: Header[] = [];
  for (let i = 0; i <= lines.length; i++) {
    headers.push(parseHeader(lines[i]));
  }
  return headers;
}

/** Parse a `name: value` line into a Header record. */
export function parseHeader(line: string): Header {
  const idx = line.indexOf(":");
  if (idx === -1) {
    throw new Error(`invalid header line: ${line}`);
  }
  return { name: line.slice(0, idx).trim(), value: line.slice(idx + 1).trim() };
}

/** Parse a single header line, returning null instead of throwing. */
export function tryParseHeader(line: string): Header | null {
  try {
    return parseHeader(line);
  } catch {
    return null;
  }
}

